<template><view class="jk-page-nav"><view class="jk-page-nav__safe" :style="{ height: statusBarHeight + 'px' }"></view><view class="jk-page-nav__bar"><view class="jk-page-nav__back" @tap="goBack">‹</view><view class="jk-page-nav__title">{{ title }}</view><view class="jk-page-nav__space"></view></view></view></template>
<script>export default { props:{title:{type:String,default:''}}, data(){return{statusBarHeight:uni.getSystemInfoSync().statusBarHeight||0}}, methods:{goBack(){const pages=getCurrentPages();if(pages.length>1){uni.navigateBack()}else{uni.switchTab({url:'/pages/user/index'})}}} };</script>
<style scoped>.jk-page-nav{background:#fff;box-shadow:0 2rpx 12rpx rgba(0,0,0,.03)}.jk-page-nav__bar{position:relative;display:flex;align-items:center;justify-content:center;height:88rpx}.jk-page-nav__back{position:absolute;left:24rpx;top:16rpx;width:56rpx;height:56rpx;border-radius:28rpx;background:#F5F7FA;color:#333;font-size:54rpx;font-weight:300;line-height:50rpx;text-align:center}.jk-page-nav__title{color:#333;font-size:31rpx;font-weight:600}.jk-page-nav__space{width:180rpx}</style>